<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class PurchaseOrder extends Model { protected $fillable=['po_number','supplier_id','purchase_requisition_id','warehouse_id','order_date','expected_date','status','subtotal','discount','tax','shipping','total','terms','note','created_by','approved_by','approved_at']; protected $casts=['order_date'=>'date','expected_date'=>'date','approved_at'=>'datetime','subtotal'=>'decimal:2','discount'=>'decimal:2','tax'=>'decimal:2','shipping'=>'decimal:2','total'=>'decimal:2']; public function supplier():BelongsTo{return $this->belongsTo(Supplier::class);} public function requisition():BelongsTo{return $this->belongsTo(PurchaseRequisition::class,'purchase_requisition_id');} public function warehouse():BelongsTo{return $this->belongsTo(Warehouse::class);} public function creator():BelongsTo{return $this->belongsTo(User::class,'created_by');} public function approver():BelongsTo{return $this->belongsTo(User::class,'approved_by');} public function items():HasMany{return $this->hasMany(PurchaseOrderItem::class);} public function goodsReceipts():HasMany{return $this->hasMany(GoodsReceipt::class);} }
